package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsLabel string // PIC X(20) len=20 = SPACES
var WsACount int64 // PIC 99 len=2 = 0
var WsTotalA int64 // PIC 999 len=3 = 0
var WsCount int64 // PIC 999 len=3 = 0

var curRec PartRec
var inputLines []string
var inputIdx int
var inputExhausted bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func formatPIC99(v int64) string {
	m := v % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func formatPIC999(v int64) string {
	m := v % 1000
	if m < 0 {
		m += 1000
	}
	return fmt.Sprintf("%03d", m)
}

func delimitedBySpace(s string) string {
	if i := strings.IndexByte(s, ' '); i >= 0 {
		return s[:i]
	}
	return s
}

func countAll(s, sub string) int64 {
	var c int64
	for i := 0; i+len(sub) <= len(s); {
		if s[i:i+len(sub)] == sub {
			c++
			i += len(sub)
		} else {
			i++
		}
	}
	return c
}

func loadInputFile() {
	WsEofFlag = "N"
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsTotalA = 0
	WsCount = 0
	inputLines = nil
	inputIdx = 0
	inputExhausted = false
	f, err := os.Open("input.dat")
	if err != nil {
		// Missing file treated as empty
		inputExhausted = true
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	// allow long lines
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)
	for sc.Scan() {
		line := sc.Text()
		// Strip trailing \r if present (CRLF)
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		inputLines = append(inputLines, line)
	}
}

func parseSerialField(raw string) int64 {
	// raw is 4 chars; DISPLAY numeric: digits only
	t := strings.TrimSpace(raw)
	if t == "" {
		return 0
	}
	// Keep only leading sign/digits? Assume digits.
	n, err := strconv.ParseInt(strings.TrimSpace(raw), 10, 64)
	if err != nil {
		// Extract digits
		digits := ""
		for _, ch := range raw {
			if ch >= '0' && ch <= '9' {
				digits += string(ch)
			}
		}
		if digits == "" {
			return 0
		}
		n, _ = strconv.ParseInt(digits, 10, 64)
		return n
	}
	if n < 0 {
		n = -n
	}
	return n % 10000
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	curRec.LbPart = line[0:8]
	curRec.LbRegion = line[8:11]
	curRec.LbSerial = parseSerialField(line[11:15])
}

func ProcessPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsACount = countAll(curRec.LbPart, "A") % 100

	pRegion := delimitedBySpace(curRec.LbRegion)
	pPart := delimitedBySpace(curRec.LbPart)
	serialStr := fmt.Sprintf("%04d", curRec.LbSerial)
	built := pRegion + "-" + pPart + "-" + serialStr
	if len(built) > 20 {
		built = built[:20]
	} else {
		built = built + strings.Repeat(" ", 20-len(built))
	}
	WsLabel = built
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")
	WsTotalA = (WsTotalA + WsACount) % 1000
	WsCount = (WsCount + 1) % 1000
	fmt.Fprint(os.Stdout, WsLabel+" A="+formatPIC99(WsACount)+"\n")
	ReadPara()
}

func SummaryPara() {
	fmt.Fprint(os.Stdout, "LABELS: "+formatPIC999(WsCount)+" A-TOTAL: "+formatPIC999(WsTotalA)+"\n")
}

func MainPara() {
	loadInputFile()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	SummaryPara()
}

func main() {
	MainPara()
}
